$ErrorActionPreference='Stop'
$qa=(Join-Path $PWD 'build/qa/admissions');$dest=Join-Path $qa 'word';New-Item -ItemType Directory -Force -Path $dest|Out-Null
foreach($phase in @('before','after')){Copy-Item -LiteralPath (Join-Path $qa ($phase+'/chrome/final.docx')) -Destination (Join-Path $dest ($phase+'.docx'))}
function FindLastPage($doc,[string]$text){$found=$null;foreach($p in $doc.Paragraphs){$value=[regex]::Replace($p.Range.Text,'[\r\x07]','').Trim();if($value -eq $text){$found=[int]$p.Range.Information(3)}};if($null -eq $found){throw ('Expected native paragraph not found: '+$text)};return $found}
$word=$null;$rows=@()
try{$word=New-Object -ComObject Word.Application;$word.Visible=$false;$word.DisplayAlerts=0;$word.AutomationSecurity=3;$version=$word.Version
foreach($phase in @('before','after')){$doc=$null;try{$file=Join-Path $dest ($phase+'.docx');$doc=$word.Documents.Open($file,$false,$true,$false);$doc.Repaginate();$text=[regex]::Replace($doc.Content.Text,'[\s\x07]','');$map=[ordered]@{attachment=(FindLastPage $doc '附件');title=(FindLastPage $doc '盘锦市2025年普通高中招生计划表');firstSchool=(FindLastPage $doc '盘锦市高级中学');lastSchool=(FindLastPage $doc '盘锦德馨学校');total=(FindLastPage $doc '合计')};if($phase -eq 'after' -and ($map.attachment -ne $map.title -or $map.title -ne $map.firstSchool -or $map.lastSchool -ne $map.total)){throw 'Attachment title/table start or final school/total still split in native Word'};$row=[ordered]@{phase=$phase;wordVersion=$version;sourceSHA256=(Get-FileHash $file).Hash;pages=$doc.ComputeStatistics(2);logicalCharacters=$text.Length;logicalTextSHA256=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($text)));pageMap=$map};$doc.ExportAsFixedFormat((Join-Path $dest ($phase+'.word.pdf')),17);$rows+=$row;ConvertTo-Json -InputObject @($rows) -Depth 6|Set-Content -LiteralPath (Join-Path $dest 'word-render.json');Write-Output ($phase+' pages '+$row.pages)}finally{if($doc){try{$doc.Close(0)}catch{Write-Output $_.Exception.Message}}}}
}finally{if($word){try{$word.Quit()}catch{Write-Output $_.Exception.Message}}}
